<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { House, Search, DataAnalysis, Setting, User, OfficeBuilding, Key, Menu as MenuIcon, Monitor } from '@element-plus/icons-vue'
import { authState, logout, hasPermission } from '../lib/auth.js'
import { api } from '../lib/api.js'
const router = useRouter()
const unreadCount = ref(0)
async function refreshNotifications() { if (hasPermission('notification.view')) { try { unreadCount.value = await api.notificationCount() } catch { unreadCount.value = 0 } } }
onMounted(() => { refreshNotifications(); window.addEventListener('erp:notifications-changed', refreshNotifications) })
onUnmounted(() => window.removeEventListener('erp:notifications-changed', refreshNotifications))
const systemVisible = computed(() => ['system.user.view','system.department.view','system.role.view','system.permission.view'].some(hasPermission))
const masterVisible = computed(() => ['system.category.view','system.unit.view','system.brand.view','system.product.view'].some(hasPermission))
const assetVisible = computed(() => hasPermission('system.device.view'))
const reportVisible = computed(() => ['inventory.stock.view','inventory.inbound.view','inventory.outbound.view','apply.requisition.view','system.device.view','inventory.stocktake.view','asset.repair.view','asset.warranty.view','asset.exchange.view'].some(hasPermission))
async function handleLogout() { try { await logout(); router.push('/login') } catch (error) { ElMessage.error(error.message) } }
</script>
<template>
    <el-container class="app-shell"><el-aside width="220px" class="app-aside"><div class="brand">ERP 管理平台</div><el-menu router default-active="/"><el-menu-item index="/"><el-icon><House /></el-icon><span>首页</span></el-menu-item><el-menu-item index="/query"><el-icon><Search /></el-icon><span>综合查询</span></el-menu-item><el-menu-item v-if="reportVisible" index="/reports"><el-icon><DataAnalysis /></el-icon><span>业务报表</span></el-menu-item><el-sub-menu v-if="systemVisible" index="/system"><template #title><el-icon><Setting /></el-icon><span>系统管理</span></template><el-menu-item v-if="hasPermission('system.user.view')" index="/system/users"><el-icon><User /></el-icon><span>用户管理</span></el-menu-item><el-menu-item v-if="hasPermission('system.department.view')" index="/system/departments"><el-icon><OfficeBuilding /></el-icon><span>部门管理</span></el-menu-item><el-menu-item v-if="hasPermission('system.role.view')" index="/system/roles"><el-icon><Key /></el-icon><span>角色管理</span></el-menu-item><el-menu-item v-if="hasPermission('system.permission.view')" index="/system/permissions"><el-icon><MenuIcon /></el-icon><span>权限管理</span></el-menu-item></el-sub-menu><el-sub-menu v-if="masterVisible" index="/master-data"><template #title><el-icon><Setting /></el-icon><span>物资管理</span></template><el-menu-item v-if="hasPermission('system.product.view')" index="/master-data/products">物资档案</el-menu-item><el-menu-item v-if="hasPermission('system.category.view')" index="/master-data/categories">分类</el-menu-item><el-menu-item v-if="hasPermission('system.brand.view')" index="/master-data/brands">品牌</el-menu-item><el-menu-item v-if="hasPermission('system.unit.view')" index="/master-data/units">单位</el-menu-item></el-sub-menu><el-menu-item v-if="assetVisible" index="/assets/devices"><el-icon><Monitor /></el-icon><span>设备管理</span></el-menu-item><el-menu-item v-if="hasPermission('system.warehouse.view')" index="/system/warehouses">仓库管理</el-menu-item><el-menu-item v-if="hasPermission('inventory.stock.view')" index="/inventory/stocks">库存查询</el-menu-item><el-menu-item v-if="hasPermission('inventory.stock.opening')" index="/inventory/openings">期初库存</el-menu-item><el-menu-item v-if="hasPermission('inventory.stock.ledger')" index="/inventory/ledgers">库存流水</el-menu-item><el-menu-item v-if="hasPermission('inventory.inbound.view')" index="/inventory/inbounds">入库单</el-menu-item><el-menu-item v-if="hasPermission('inventory.outbound.view')" index="/inventory/outbounds">出库单</el-menu-item><el-menu-item v-if="hasPermission('apply.requisition.view')" index="/apply/requisitions">领用申请</el-menu-item><el-menu-item v-if="hasPermission('inventory.stocktake.view')" index="/inventory/stocktakes">库存盘点</el-menu-item><el-menu-item v-if="hasPermission('asset.repair.view')" index="/assets/repairs">维修管理</el-menu-item><el-menu-item v-if="hasPermission('asset.warranty.view')" index="/assets/warranties">保修管理</el-menu-item><el-menu-item v-if="hasPermission('asset.exchange.view')" index="/assets/exchanges">换货管理</el-menu-item><el-menu-item v-if="hasPermission('asset.qr.view')" index="/assets/qr">二维码与扫码</el-menu-item></el-menu></el-aside><el-container><el-header class="app-header"><span>公司内部物资管理系统</span><div class="user-actions"><el-badge v-if="hasPermission('notification.view')" :value="unreadCount" :hidden="!unreadCount"><el-button link @click="router.push('/notifications')">站内通知</el-button></el-badge><span>{{ authState.user?.realName || authState.user?.username }}</span><el-button link @click="handleLogout">退出登录</el-button></div></el-header><el-main class="app-main"><RouterView /></el-main></el-container></el-container>
</template>
